def main() -> None:
    linhas = [[c.strip() for c in l.split(" | ")] for l in DADOS.strip().splitlines()]
    assert len(linhas) == 50 and all(len(l) == 9 for l in linhas), [l[0] for l in linhas if len(l) != 9]
    jogo = RAIZ / "index.html"
    s = jogo.read_text(encoding="utf-8")
    if '{ id: "ana"' in s:
        print("os 50 santos já estão no jogo; nada a fazer")
        return

    entradas = "".join(
        f'    {{ id: "{i}", name: "{nome}", feast: "{festa}", hue: {(n * 47 + 13) % 360},\n      why: "{why}" }},\n'
        for n, (i, nome, festa, _sexo, _nivel, why, *_resto) in enumerate(linhas))
    fim = '        g("translate(192,306) scale(.75)", openBook(C.dkbrown)) },\n  ];'
    assert fim in s
    s = s.replace(fim, fim[:-4] + "    // Preparados em 10/10/2026: sem desenho de reserva; só aparecem no jogo quando tiverem as duas imagens aprovadas\n" + entradas + "  ];")

    def acrescenta(nome: str, ids: list[str]) -> None:
        nonlocal s
        ini = s.index(f'const {nome} = "') + len(f'const {nome} = "')
        fim_lista = s.index('"', ini)
        s = s[:fim_lista] + " " + " ".join(ids) + s[fim_lista:]

    acrescenta("EASY", [l[0] for l in linhas if l[4] == "F"])
    acrescenta("HARD", [l[0] for l in linhas if l[4] == "D"])
    acrescenta("WOMEN", [l[0] for l in linhas if l[3] == "f"])
    jogo.write_text(s, encoding="utf-8", newline="\n")

    prompts = RAIZ / "prompts-higgsfield.md"
    p = prompts.read_text(encoding="utf-8").rstrip("\n")
    p = p.replace("# Prompts para o Higgsfield: 69 santos, duas séries", "# Prompts para o Higgsfield: 119 santos, duas séries")
    p += "\n" + "\n".join(
        f"| {70 + n} | {i} | {nome} | {fig} | {conf} | {obj} |"
        for n, (i, nome, _f, _s, _n, _w, fig, conf, obj) in enumerate(linhas)) + "\n"
    prompts.write_text(p, encoding="utf-8", newline="\n")
    print("50 santos acrescentados ao jogo e ao arquivo de prompts")


if __name__ == "__main__":
    main()
